let colors = ['#f71735', '#f293af', '#fdb50e', '#2abde4', '#232323', '#2864b8', '#f4f0e6'];
let ctx;
let centerX, centerY;

function setup() {
	createCanvas(900, 900);
	rectMode(CENTER);
	angleMode(DEGREES)
	colorMode(HSB, 360, 100, 100, 100);
	ctx = drawingContext;
	centerX = width / 2;
	centerY = height / 2;
	background('#f4f0e6');
	createPattern(centerX, centerY, width * 1.1, 8);
}

function draw() {
  // === Variant 2: Organic Lissajous Morph ===
  scalePulse = 1.0 + 0.25 * sin(frameCount * 0.03);
  rotAngle = frameCount * 0.015;
  push();
  translate(width/2, height/2);
  rotate(rotAngle);
  scale(scalePulse);
  translate(-width/2, -height/2);



  pop();
}

function createPattern(x, y, w, cellCount) {
	let cellSize = w / cellCount;
	let size = cellSize * 0.981;
	for (let i = 0; i < cellCount; i++) {
		for (let j = 0; j < cellCount; j++) {
			let cellX = i * cellSize + (cellSize / 2) + (x - (w / 2));
			let cellY = j * cellSize + (cellSize / 2) + (y - (w / 2));
			let ang = 11.3 + (int(random(4)) * (90));
			noStroke();
			form(cellX, cellY, size, ang);
			if (((cellCount - 1) != i) || ((cellCount - 1) != j)) {
				form(cellX + cellSize / 2, cellY + cellSize / 2, size, ang);
			}
		}
	}
}

function form(x, y, w, a) {
	let ww = w / 10;
	let type = int(random(4));
	push();
	translate(x, y);
	rotate(a);
	noFill();
	stroke('#000');
	strokeWeight(w * 0.013);
	if (type == 0) {

		beginShape();
		vertex(-w * 0.2, -w * 0.5);
		vertex(-w * 0.2, -w * 0.2);
		vertex(-w * 0, -w * 0.2);
		vertex(-w * 0, w * 0);
		vertex(w * 0.2, w * 0);
		vertex(w * 0.2, w * 0.25);
		endShape();


		beginShape();
		vertex(-w * 0.4, w * 0.15);
		vertex(-w * 0.3, w * 0.15);
		vertex(-w * 0.3, w * 0.25);
		vertex(-w * 0.2, w * 0.25);
		vertex(-w * 0.2, w * 0.15);
		vertex(-w * 0.1, w * 0.15);
		vertex(-w * 0.1, w * 0.25);
		vertex(-w * 0, w * 0.25);
		vertex(-w * 0, w * 0.15);
		vertex(w * 0.1, w * 0.15);
		endShape();

		line(-w * 0.25, -w * 0.15, -w * 0.05, -w * 0.15);
		line(-w * 0.2, -w * 0.1, -w * 0.05, -w * 0.1);
		line(w * 0.025, -w * 0.05, w * 0.025, -w * 0.2);
		line(w * 0.15, w * 0.46, w * 0.25, w * 0.46);

		fill(random(colors));
		circle(w * 0.175, -w * 0.15, w * 0.2);
		fill(random(colors));
		circle(w * 0.4, -w * 0.2, w * 0.15);
		fill(random(colors));
		circle(-w * 0.25, w * 0.2, w * 0.05);
		fill(random(colors));
		circle(-w * 0.05, w * 0.2, w * 0.05);
		fill(random(colors));
		rect(w * 0.2, w * 0.35, w * 0.1, w * 0.15);
	}
	else if (type == 1) {
		arc(w * 0.2, 0, w * 0.1, w * 0.2, 90, 270);
		arc(w * 0.2, w * 0.2, w * 0.1, w * 0.2, -90, 90);
		arc(w * 0.2, w * 0.4, w * 0.1, w * 0.2, 90, 270);

		line(-w * 0.45, w * 0.2, -w * 0.3, w * 0.2);
		line(-w * 0.45, w * 0.15, -w * 0.3, w * 0.15);
		line(-w * 0.45, w * 0.25, -w * 0.3, w * 0.25);
		line(0, w * 0.25, 0, -w * 0.1);
		line(-w * 0.2, w * 0, w * 0.05, -w * 0);
		line(-w * 0.2, w * 0.05, w * 0.05, w * 0.05);
		fill(random(colors));
		beginShape();
		vertex(-w * 0.25, -w * 0.45);
		vertex(-w * 0.15, -w * 0.45);
		vertex(-w * 0.15, -w * 0.25);
		vertex(-w * 0.1, -w * 0.25);
		vertex(-w * 0.1, -w * 0.15);
		vertex(-w * 0.25, -w * 0.15);
		endShape(CLOSE);
		fill(random(colors));
		arc(-w * 0.3, w * 0.2, w * 0.2, w * 0.2, -90, 90, PIE);
		fill(random(colors));
		rect(0, -w * 0.2, w * 0.1, w * 0.1);
		fill(random(colors));
		circle(w * 0.1, -w * 0.2, w * 0.05);
		fill(random(colors));
		circle(w * 0.2, -w * 0.2, w * 0.05);
		fill(random(colors));
		circle(w * 0.3, -w * 0.2, w * 0.05);
		fill(random(colors));
		circle(w * 0.4, -w * 0.2, w * 0.05);
		fill(random(colors));
		circle(w * 0.2, w * 0.0, w * 0.05);
		fill(random(colors));
		circle(w * 0.2, w * 0.2, w * 0.05);
	}
	else if (type == 2) {
		line(-w * 0.225, -w * 0.2, w * 0.4, -w * 0.2);
		line(-w * 0.225, -w * 0.17, w * 0.4, -w * 0.17);
		line(-w * 0.5, w * 0.2, w * 0.3, w * 0.2);
		line(-w * 0.5, w * 0.17, w * 0.3, w * 0.17);
		line(-w * 0.2, w * 0.2, -w * 0.2, -w * 0.4);
		line(w * 0.1, w * 0.2, -w * 0.2, -w * 0.4);
		line(w * 0.05, -w * 0.1, w * 0.25, w * 0.1);
		line(w * 0.05, w * 0.0, w * 0.15, -w * 0.1);
		line(w * 0.1, w * 0.05, w * 0.2, -w * 0.05);
		line(w * 0.15, w * 0.1, w * 0.25, w * 0);

		fill(random(colors));
		circle(-w * 0.2, -w * 0.45, w * 0.05);

		fill(random(colors));
		beginShape();
		vertex(w * 0.1, w * 0.3);
		vertex(w * 0.3, w * 0.3);
		vertex(w * 0.2, w * 0.5);
		endShape(CLOSE);

		fill(random(colors));
		beginShape();
		vertex(-w * 0.1, w * 0.0);
		vertex(-w * 0.18, w * 0.0);
		vertex(-w * 0.1, w * 0.2);
		endShape(CLOSE);
	}
	else if (type == 3) {
		line(-w * 0.1, -w * 0.2, w * 0.45, -w * 0.2);
		line(-w * 0.05, -w * 0.25, w * 0.2, w * 0.1);
		line(w * 0.2, -w * 0.25, w * 0.2, w * 0.1);

		fill(random(colors));
		arc(-w * 0.2, -w * 0.4, w * 0.15, w * 0.15, 180, 360, PIE);
		fill(random(colors));
		beginShape();
		vertex(-w * 0.275, -w * 0.37);
		vertex(-w * 0.125, -w * 0.37);
		vertex(-w * 0.2, -w * 0.1);
		endShape(CLOSE);
		fill(random(colors));
		beginShape();
		vertex(-w * 0.48, w * 0.2);
		vertex(-w * 0.32, w * 0.15);
		vertex(-w * 0.32, w * 0.25);
		endShape(CLOSE);
		fill(random(colors));
		beginShape();
		vertex(w * 0.275, w * 0.1);
		vertex(w * 0.275, w * 0.45);
		vertex(w * 0.125, w * 0.45);
		endShape(CLOSE);
		fill(random(colors));
		beginShape();
		vertex(w * 0.05, -w * 0.05);
		vertex(w * 0.05, w * 0.25);
		vertex(-w * 0.175, w * 0.25);
		vertex(-w * 0.175, w * 0.15);
		vertex(-w * 0.05, w * 0.15);
		vertex(-w * 0.05, -w * 0.05);
		endShape(CLOSE);
		fill(random(colors));
		rect(-w * 0.25, w * 0.2, w * 0.1);
	}
	pop();
}


